function parseAsn(s){
  s=(s||'').trim();
  if(!s) return {valid:false,error:'空输入'};
  var m=s.match(/^(?:AS ?)?(\d+)$/i);
  if(!m) return {valid:false,error:'无法解析为 AS 号（应为 AS\\d+ 或纯数字）'};
  var num=parseInt(m[1],10);
  if(num>4294967295) return {valid:false,error:'超出 32 位 AS 范围'};
  var kind = num<=65535 ? '16-bit' : '32-bit';
  var reserved=false, note='';
  if(num===0){ reserved=true; note='AS0 保留（不分配给任何网络）'; }
  else if(num>=64496 && num<=64511){ reserved=true; note='文档/示例保留段'; }
  else if(num>=64512 && num<=65534){ reserved=true; note='私有 AS 段（64512-65534）'; }
  else if(num===65535){ reserved=true; note='AS65535 保留'; }
  else if(num>=4200000000 && num<=4294967295){ reserved=true; note='私有 32-bit AS 段'; }
  return {valid:true, raw:s, num:num, asdot:'AS'+num, kind:kind, reserved:reserved, note:note};
}

var EXPORTS={parseAsn:parseAsn};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AsnForgePure = EXPORTS; }
